  1→import { useEffect, useState } from "react";
  2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
  3→import { useLoaderData, useFetcher } from "react-router";
  4→import { useAppBridge } from "@shopify/app-bridge-react";
  5→import { authenticate } from "../shopify.server";
  6→import db from "../db.server";
  7→import { getPlan, canCreateChart } from "../lib/plans";
  8→import { SIZE_CHART_TEMPLATES, getCategories } from "../lib/templates";
  9→
 10→export const loader = async ({ request }: LoaderFunctionArgs) => {
 11→  const { session } = await authenticate.admin(request);
 12→  const shop = session.shop;
 13→
 14→  const [charts, subscription] = await Promise.all([
 15→    db.sizeChart.findMany({
 16→      where: { shop },
 17→      orderBy: { updatedAt: "desc" },
 18→      include: { assignments: true },
 19→    }),
 20→    db.subscription.findUnique({ where: { shop } }),
 21→  ]);
 22→
 23→  const plan = getPlan(subscription?.planId ?? "free");
 24→  const templates = SIZE_CHART_TEMPLATES.map((t) => ({
 25→    name: t.name,
 26→    category: t.category,
 27→    gender: t.gender,
 28→  }));
 29→
 30→  return { charts, plan, templates, canCreate: canCreateChart(plan.id, charts.length) };
 31→};
 32→
 33→export const action = async ({ request }: ActionFunctionArgs) => {
 34→  const { session } = await authenticate.admin(request);
 35→  const shop = session.shop;
 36→  const formData = await request.formData();
 37→  const intent = formData.get("intent") as string;
 38→
 39→  try {
 40→    switch (intent) {
 41→      case "create-from-template": {
 42→        const templateName = formData.get("templateName") as string;
 43→        const template = SIZE_CHART_TEMPLATES.find((t) => t.name === templateName);
 44→        if (!template) return { error: "Template not found" };
 45→
 46→        const subscription = await db.subscription.findUnique({ where: { shop } });
 47→        const plan = getPlan(subscription?.planId ?? "free");
 48→        const chartCount = await db.sizeChart.count({ where: { shop } });
 49→        if (!canCreateChart(plan.id, chartCount)) {
 50→          return { error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.` };
 51→        }
 52→
 53→        let name = template.name;
 54→        const existing = await db.sizeChart.findUnique({ where: { shop_name: { shop, name } } });
 55→        if (existing) name = `${template.name} (${Date.now().toString(36)})`;
 56→
 57→        await db.sizeChart.create({
 58→          data: { shop, name, category: template.category, data: JSON.stringify(template.data), status: "active" },
 59→        });
 60→        return { ok: true, message: `"${name}" created successfully` };
 61→      }
 62→
 63→      case "create-blank": {
 64→        const name = (formData.get("name") as string) || "Untitled Size Chart";
 65→        const category = (formData.get("category") as string) || "general";
 66→
 67→        const subscription = await db.subscription.findUnique({ where: { shop } });
 68→        const plan = getPlan(subscription?.planId ?? "free");
 69→        const chartCount = await db.sizeChart.count({ where: { shop } });
 70→        if (!canCreateChart(plan.id, chartCount)) {
 71→          return { error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.` };
 72→        }
 73→
 74→        let uniqueName = name;
 75→        const existing = await db.sizeChart.findUnique({ where: { shop_name: { shop, name } } });
 76→        if (existing) uniqueName = `${name} (${Date.now().toString(36)})`;
 77→
 78→        const defaultData = {
 79→          headers: ["Size", "Chest", "Waist", "Hips"],
 80→          units: { default: "in", available: ["in", "cm"] },
 81→          rows: [
 82→            { size: "S", chest: "", waist: "", hips: "" },
 83→            { size: "M", chest: "", waist: "", hips: "" },
 84→            { size: "L", chest: "", waist: "", hips: "" },
 85→          ],
 86→        };
 87→
 88→        await db.sizeChart.create({
 89→          data: { shop, name: uniqueName, category, data: JSON.stringify(defaultData), status: "draft" },
 90→        });
 91→        return { ok: true, message: `"${uniqueName}" created` };
 92→      }
 93→
 94→      case "delete": {
 95→        const id = formData.get("id") as string;
 96→        await db.sizeChart.deleteMany({ where: { id, shop } });
 97→        return { ok: true, message: "Chart deleted" };
 98→      }
 99→
100→      case "duplicate": {
101→        const sourceId = formData.get("id") as string;
102→        const source = await db.sizeChart.findFirst({ where: { id: sourceId, shop } });
103→        if (!source) return { error: "Chart not found" };
104→
105→        const subscription = await db.subscription.findUnique({ where: { shop } });
106→        const plan = getPlan(subscription?.planId ?? "free");
107→        const chartCount = await db.sizeChart.count({ where: { shop } });
108→        if (!canCreateChart(plan.id, chartCount)) {
109→          return { error: "Chart limit reached. Upgrade your plan." };
110→        }
111→
112→        const newName = `${source.name} (Copy)`;
113→        await db.sizeChart.create({
114→          data: { shop, name: newName, type: source.type, category: source.category, data: source.data, status: "draft" },
115→        });
116→        return { ok: true, message: `Duplicated as "${newName}"` };
117→      }
118→
119→      case "toggle-status": {
120→        const chartId = formData.get("id") as string;
121→        const chart = await db.sizeChart.findFirst({ where: { id: chartId, shop } });
122→        if (!chart) return { error: "Chart not found" };
123→
124→        const newStatus = chart.status === "active" ? "draft" : "active";
125→        await db.sizeChart.update({ where: { id: chartId }, data: { status: newStatus } });
126→        return { ok: true, message: `Chart ${newStatus === "active" ? "published" : "unpublished"}` };
127→      }
128→
129→      default:
130→        return { error: "Unknown action" };
131→    }
132→  } catch (error) {
133→    const message = error instanceof Error ? error.message : "An unexpected error occurred";
134→    if (message.includes("Unique constraint")) {
135→      return { error: "A chart with this name already exists." };
136→    }
137→    return { error: message };
138→  }
139→};
140→
141→export default function SizeCharts() {
142→  const { charts, plan, templates, canCreate } = useLoaderData<typeof loader>();
143→  const fetcher = useFetcher<typeof action>();
144→  const shopify = useAppBridge();
145→  const [showTemplates, setShowTemplates] = useState(false);
146→
147→  useEffect(() => {
148→    if (fetcher.data && "ok" in fetcher.data && fetcher.data.ok) {
149→      shopify.toast.show(fetcher.data.message ?? "Success");
150→      setShowTemplates(false);
151→    } else if (fetcher.data && "error" in fetcher.data) {
152→      shopify.toast.show(fetcher.data.error ?? "Error", { isError: true });
153→    }
154→  }, [fetcher.data, shopify]);
155→
156→  const isLoading = fetcher.state !== "idle";
157→
158→  return (
159→    <s-page heading="Size Charts">
160→      <s-button
161→        slot="primary-action"
162→        variant="primary"
163→        onClick={() => setShowTemplates(!showTemplates)}
164→        disabled={!canCreate}
165→      >
166→        {canCreate ? "Create Chart" : `Limit reached (${plan.limits.maxCharts})`}
167→      </s-button>
168→
169→      {showTemplates && (
170→        <s-section heading="Choose a Template">
171→          <s-paragraph>
172→            Start from a pre-built template or create a blank chart.
173→          </s-paragraph>
174→          <s-stack direction="inline" gap="base">
175→            {templates.map((template) => (
176→              <s-box key={template.name} padding="base" borderWidth="base" borderRadius="base" background="subdued">
177→                <s-stack direction="block" gap="small-200">
178→                  <s-text>{template.name}</s-text>
179→                  <s-text tone="neutral">{template.category} · {template.gender}</s-text>
180→                  <fetcher.Form method="post">
181→                    <input type="hidden" name="intent" value="create-from-template" />
182→                    <input type="hidden" name="templateName" value={template.name} />
183→                    <s-button variant="primary" type="submit" loading={isLoading}>
184→                      Use Template
185→                    </s-button>
186→                  </fetcher.Form>
187→                </s-stack>
188→              </s-box>
189→            ))}
190→            <s-box padding="base" borderWidth="base" borderRadius="base" background="subdued">
191→              <s-stack direction="block" gap="small-200">
192→                <s-text>Blank Chart</s-text>
193→                <s-text tone="neutral">Start from scratch</s-text>
194→                <fetcher.Form method="post">
195→                  <input type="hidden" name="intent" value="create-blank" />
196→                  <input type="hidden" name="name" value="Untitled Size Chart" />
197→                  <input type="hidden" name="category" value="general" />
198→                  <s-button type="submit" loading={isLoading}>Create Blank</s-button>
199→                </fetcher.Form>
200→              </s-stack>
201→            </s-box>
202→          </s-stack>
203→        </s-section>
204→      )}
205→
206→      <s-section heading={`All Charts (${charts.length})`}>
207→        {charts.length === 0 ? (
208→          <s-box padding="large-200">
209→            <s-stack direction="block" gap="base">
210→              <s-heading>No size charts yet</s-heading>
211→              <s-paragraph>
212→                Size charts help your customers find their perfect fit and can reduce
213→                size-related returns by up to 40%.
214→              </s-paragraph>
215→              <s-button variant="primary" onClick={() => setShowTemplates(true)}>
216→                Create your first chart
217→              </s-button>
218→            </s-stack>
219→          </s-box>
220→        ) : (
221→          <s-stack direction="block" gap="small-200">
222→            {charts.map((chart) => (
223→              <s-box key={chart.id} padding="base" borderWidth="base" borderRadius="base">
224→                <s-stack direction="inline" gap="base">
225→                  <s-stack direction="block" gap="small-100">
226→                    <s-text>{chart.name}</s-text>
227→                    <s-text tone="neutral">
228→                      {chart.category} ·{" "}
229→                      {chart.status === "active" ? "Published" : "Draft"} ·{" "}
230→                      {chart.assignments.length} assignment{chart.assignments.length !== 1 ? "s" : ""}
231→                    </s-text>
232→                  </s-stack>
233→                  <s-stack direction="inline" gap="small-200">
234→                    <fetcher.Form method="post">
235→                      <input type="hidden" name="intent" value="toggle-status" />
236→                      <input type="hidden" name="id" value={chart.id} />
237→                      <s-button type="submit" loading={isLoading}>
238→                        {chart.status === "active" ? "Unpublish" : "Publish"}
239→                      </s-button>
240→                    </fetcher.Form>
241→                    <fetcher.Form method="post">
242→                      <input type="hidden" name="intent" value="duplicate" />
243→                      <input type="hidden" name="id" value={chart.id} />
244→                      <s-button type="submit" loading={isLoading}>Duplicate</s-button>
245→                    </fetcher.Form>
246→                    <fetcher.Form method="post">
247→                      <input type="hidden" name="intent" value="delete" />
248→                      <input type="hidden" name="id" value={chart.id} />
249→                      <s-button type="submit" variant="tertiary" tone="critical" loading={isLoading}>
250→                        Delete
251→                      </s-button>
252→                    </fetcher.Form>
253→                  </s-stack>
254→                </s-stack>
255→              </s-box>
256→            ))}
257→          </s-stack>
258→        )}
259→      </s-section>
260→
261→      <s-section slot="aside" heading="Chart Limits">
262→        <s-stack direction="block" gap="small-200">
263→          <s-text>
264→            {plan.limits.maxCharts === -1 ? "Unlimited charts" : `${charts.length} / ${plan.limits.maxCharts} charts used`}
265→          </s-text>
266→          <s-text tone="neutral">{plan.name} Plan</s-text>
267→          {plan.limits.maxCharts !== -1 && (
268→            <s-button href="/app/pricing">Upgrade for unlimited</s-button>
269→          )}
270→        </s-stack>
271→      </s-section>
272→
273→      <s-section slot="aside" heading="Tips">
274→        <s-unordered-list>
275→          <s-list-item>Assign charts to products or collections for automatic display</s-list-item>
276→          <s-list-item>Use templates — they include standard sizing data</s-list-item>
277→          <s-list-item>Preview charts on your storefront after publishing</s-list-item>
278→        </s-unordered-list>
279→      </s-section>
280→    </s-page>
281→  );
282→}
