  kids: "Kids",
  rings: "Rings",
  sportswear: "Sportswear",
  general: "General",
};

function formatDate(date: string | Date): string {
  return new Date(date).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

