import { useEffect, useRef, useState } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, redirect } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ChartData {
  headers: string[];
  units: { default: string; available: string[] };
  rows: Record<string, string>[];
}

interface Assignment {
  id: string;
  assignmentType: string;
  assignmentValue: string;
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const { id } = params as { id: string };

  if (id === "new") {
    return {
      chart: null as null,
      assignments: [] as Assignment[],
      isNew: true,
    };
  }

  const chart = await db.sizeChart.findFirst({
    where: { id, shop },
    include: { assignments: true },
  });

  if (!chart) {
    throw new Response("Not found", { status: 404 });
  }

  return {
    chart: {
      id: chart.id,
      name: chart.name,
      category: chart.category,
      status: chart.status,
      data: chart.data,
      createdAt: chart.createdAt.toISOString(),
      updatedAt: chart.updatedAt.toISOString(),
    },
    assignments: chart.assignments.map((a) => ({
      id: a.id,
      assignmentType: a.assignmentType,
      assignmentValue: a.assignmentValue,
    })),
    isNew: false,
  };
};

// ---------------------------------------------------------------------------
// Action
// ---------------------------------------------------------------------------

export const action = async ({ request, params }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const { id } = params as { id: string };
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "save": {
        const name = formData.get("name") as string;
        const category = formData.get("category") as string;
        const status = formData.get("status") as string;
        const dataRaw = formData.get("data") as string;

        if (!name?.trim()) return { error: "Chart name is required" };

        let parsedData: ChartData;
        try {
          parsedData = JSON.parse(dataRaw) as ChartData;
        } catch {
          return { error: "Invalid chart data. Please try again." };
        }

        if (id === "new") {
          const chart = await db.sizeChart.create({
            data: {
              shop,
              name: name.trim(),
              category,
              status,
              data: JSON.stringify(parsedData),
            },
          });
          return redirect(`/app/size-charts/${chart.id}?saved=1`);
        }

        const existing = await db.sizeChart.findFirst({ where: { id, shop } });
        if (!existing) return { error: "Chart not found" };

        await db.sizeChart.update({
          where: { id },
          data: {
            name: name.trim(),
            category,
            status,
            data: JSON.stringify(parsedData),
          },
        });
        return { ok: true, message: "Chart saved successfully" };
      }

      case "toggle-status": {
        const chart = await db.sizeChart.findFirst({ where: { id, shop } });
        if (!chart) return { error: "Chart not found" };
        const newStatus = chart.status === "active" ? "draft" : "active";
        await db.sizeChart.update({ where: { id }, data: { status: newStatus } });
        return {
          ok: true,
          message: newStatus === "active" ? "Chart published" : "Chart unpublished",
          newStatus,
        };
      }

      case "add-assignment": {
        const assignmentType = formData.get("assignmentType") as string;
        const assignmentValue = formData.get("assignmentValue") as string;

        if (!assignmentValue?.trim()) {
          return { error: "Assignment value is required" };
        }

        await db.chartAssignment.upsert({
          where: {
            shop_sizeChartId_assignmentType_assignmentValue: {
              shop,
              sizeChartId: id,
              assignmentType,
              assignmentValue: assignmentValue.trim(),
            },
          },
          create: {
            shop,
            sizeChartId: id,
            assignmentType,
            assignmentValue: assignmentValue.trim(),
          },
          update: {},
        });
        return { ok: true, message: "Assignment added" };
      }

      case "remove-assignment": {
        const assignmentId = formData.get("assignmentId") as string;
        await db.chartAssignment.deleteMany({
          where: { id: assignmentId, shop },
        });
        return { ok: true, message: "Assignment removed" };
      }

      case "delete": {
        await db.sizeChart.deleteMany({ where: { id, shop } });
        return redirect("/app/size-charts");
      }

      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "An unexpected error occurred";
    if (message.includes("Unique constraint")) {
      return { error: "A chart with this name already exists." };
    }
    return { error: message };
  }
};

