const CATEGORIES = [
  { value: "general", label: "General" },
  { value: "tops", label: "Tops" },
  { value: "bottoms", label: "Bottoms" },
  { value: "dresses", label: "Dresses" },
  { value: "shoes", label: "Shoes" },
  { value: "kids", label: "Kids" },
  { value: "rings", label: "Rings" },
  { value: "sportswear", label: "Sportswear" },
];

const ASSIGNMENT_TYPES = [
  { value: "product", label: "Product ID" },
  { value: "collection", label: "Collection ID" },
  { value: "tag", label: "Product Tag" },
  { value: "product_type", label: "Product Type" },
  { value: "all", label: "All Products" },
];

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function makeDefaultData(): ChartData {
  return {
    headers: ["Size", "Chest", "Waist", "Hips"],
    units: { default: "in", available: ["in", "cm"] },
    rows: [
      { Size: "S", Chest: "", Waist: "", Hips: "" },
      { Size: "M", Chest: "", Waist: "", Hips: "" },
      { Size: "L", Chest: "", Waist: "", Hips: "" },
    ],
  };
}

function parseChartData(raw: string): ChartData {
  try {
    const parsed = JSON.parse(raw) as ChartData;
    if (
      Array.isArray(parsed.headers) &&
      parsed.units &&
      Array.isArray(parsed.rows)
    ) {
      return parsed;
    }
  } catch {
    // fall through
  }
  return makeDefaultData();
}

// ---------------------------------------------------------------------------
// Table Editor Component
// ---------------------------------------------------------------------------

interface TableEditorProps {
  data: ChartData;
  onChange: (data: ChartData) => void;
}

function TableEditor({ data, onChange }: TableEditorProps) {
  const headerInputRefs = useRef<(HTMLInputElement | null)[]>([]);

  const updateCell = (rowIndex: number, header: string, value: string) => {
    const newRows = data.rows.map((row, i) => {
      if (i !== rowIndex) return row;
      return { ...row, [header]: value };
    });
    onChange({ ...data, rows: newRows });
  };

  const updateHeader = (headerIndex: number, value: string) => {
    const oldHeader = data.headers[headerIndex];
    const newHeaders = data.headers.map((h, i) => (i === headerIndex ? value : h));
    const newRows = data.rows.map((row) => {
      const newRow: Record<string, string> = {};
      data.headers.forEach((h, i) => {
        const key = i === headerIndex ? value : h;
        newRow[key] = row[h] ?? "";
      });
      return newRow;
    });
    onChange({ ...data, headers: newHeaders, rows: newRows });
    // suppress unused variable warning
    void oldHeader;
  };

  const addRow = () => {
    const emptyRow: Record<string, string> = {};
    data.headers.forEach((h) => {
      emptyRow[h] = "";
    });
    onChange({ ...data, rows: [...data.rows, emptyRow] });
  };

  const removeRow = (rowIndex: number) => {
    onChange({ ...data, rows: data.rows.filter((_, i) => i !== rowIndex) });
  };

  const addColumn = () => {
    const newHeader = `Column ${data.headers.length + 1}`;
    const newHeaders = [...data.headers, newHeader];
    const newRows = data.rows.map((row) => ({ ...row, [newHeader]: "" }));
    onChange({ ...data, headers: newHeaders, rows: newRows });
  };

  const removeColumn = (headerIndex: number) => {
    if (data.headers.length <= 1) return;
    const removedHeader = data.headers[headerIndex];
    const newHeaders = data.headers.filter((_, i) => i !== headerIndex);
    const newRows = data.rows.map((row) => {
      const newRow: Record<string, string> = {};
      newHeaders.forEach((h) => {
        newRow[h] = row[h] ?? "";
      });
      return newRow;
    });
    onChange({ ...data, headers: newHeaders, rows: newRows });
    void removedHeader;
  };

  const toggleUnit = (unit: string) => {
    onChange({ ...data, units: { ...data.units, default: unit } });
  };

  return (
    <div>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "8px",
          marginBottom: "16px",
        }}
      >
        <s-text tone="neutral">Unit system:</s-text>
        {data.units.available.map((unit) => (
          <button
            key={unit}
            type="button"
            onClick={() => toggleUnit(unit)}
            style={{
              padding: "4px 12px",
              borderRadius: "4px",
              border: "1px solid",
              borderColor: data.units.default === unit ? "#2c6ecb" : "#8c9196",
              background: data.units.default === unit ? "#f0f7ff" : "#fff",
              color: data.units.default === unit ? "#2c6ecb" : "#333",
              fontWeight: data.units.default === unit ? 600 : 400,
              cursor: "pointer",
              fontSize: "13px",
            }}
          >
            {unit}
          </button>
        ))}
        <s-text tone="neutral" style={{ marginLeft: "auto", fontSize: "12px" }}>
          {data.rows.length} rows · {data.headers.length} columns
        </s-text>
      </div>

      <div style={{ overflowX: "auto" }}>
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            fontSize: "14px",
          }}
        >
          <thead>
            <tr>
              {data.headers.map((header, hi) => (
                <th
                  key={hi}
                  style={{
                    background: "#f6f6f7",
                    border: "1px solid #e1e3e5",
                    padding: "0",
                    position: "relative",
                    minWidth: "100px",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      padding: "4px 4px 4px 8px",
                    }}
                  >
                    <input
                      ref={(el) => {
                        headerInputRefs.current[hi] = el;
                      }}
                      value={header}
                      onChange={(e) =>
                        updateHeader(hi, (e.target as HTMLInputElement).value)
                      }
                      style={{
                        flex: 1,
                        border: "none",
                        background: "transparent",
                        fontWeight: 600,
                        fontSize: "13px",
                        color: "#202223",
                        padding: "6px 4px",
                        outline: "none",
                        minWidth: "60px",
                      }}
                      placeholder={`Column ${hi + 1}`}
                    />
                    {data.headers.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeColumn(hi)}
                        title="Remove column"
                        style={{
                          background: "none",
                          border: "none",
                          cursor: "pointer",
                          color: "#8c9196",
                          padding: "2px 4px",
                          borderRadius: "3px",
                          fontSize: "14px",
                          lineHeight: 1,
                          flexShrink: 0,
                        }}
                        onMouseEnter={(e) => {
                          (e.currentTarget as HTMLButtonElement).style.color = "#d82c0d";
                        }}
                        onMouseLeave={(e) => {
                          (e.currentTarget as HTMLButtonElement).style.color = "#8c9196";
                        }}
                      >
                        ×
                      </button>
                    )}
                  </div>
                </th>
              ))}
              <th
                style={{
                  background: "#f6f6f7",
                  border: "1px solid #e1e3e5",
                  padding: "8px",
                  width: "48px",
                }}
              >
                <button
                  type="button"
                  onClick={addColumn}
                  title="Add column"
                  style={{
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "#2c6ecb",
                    fontSize: "18px",
                    lineHeight: 1,
                    padding: "0 4px",
                  }}
                >
                  +
                </button>
              </th>
            </tr>
          </thead>
          <tbody>
            {data.rows.map((row, ri) => (
              <tr
                key={ri}
                style={{ background: ri % 2 === 0 ? "#fff" : "#fafbfb" }}
              >
                {data.headers.map((header, hi) => (
                  <td
                    key={hi}
                    style={{
                      border: "1px solid #e1e3e5",
                      padding: "0",
                    }}
                  >
                    <input
                      value={row[header] ?? ""}
                      onChange={(e) =>
                        updateCell(ri, header, (e.target as HTMLInputElement).value)
                      }
                      style={{
                        width: "100%",
                        border: "none",
                        background: "transparent",
                        padding: "10px 12px",
                        fontSize: "13px",
                        color: "#202223",
                        outline: "none",
                        boxSizing: "border-box",
                      }}
                      placeholder="—"
                    />
                  </td>
                ))}
                <td
                  style={{
                    border: "1px solid #e1e3e5",
                    padding: "4px",
                    textAlign: "center",
                    background: ri % 2 === 0 ? "#fff" : "#fafbfb",
                  }}
                >
                  <button
                    type="button"
                    onClick={() => removeRow(ri)}
                    title="Remove row"
                    style={{
                      background: "none",
                      border: "none",
                      cursor: "pointer",
                      color: "#8c9196",
                      fontSize: "16px",
                      lineHeight: 1,
                      padding: "2px 6px",
                      borderRadius: "3px",
                    }}
                    onMouseEnter={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color = "#d82c0d";
                    }}
                    onMouseLeave={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color = "#8c9196";
                    }}
                  >
                    ×
                  </button>
                </td>
              </tr>
            ))}
            <tr>
              <td
                colSpan={data.headers.length + 1}
                style={{
                  border: "1px solid #e1e3e5",
                  padding: "8px 12px",
                  background: "#f6f6f7",
                }}
              >
                <button
                  type="button"
                  onClick={addRow}
                  style={{
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "#2c6ecb",
                    fontSize: "13px",
                    fontWeight: 500,
                    padding: "0",
                  }}
                >
                  + Add row
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

