interface ChartPreviewProps {
  data: ChartData;
  name: string;
}

function ChartPreview({ data, name }: ChartPreviewProps) {
  return (
    <div
      style={{
        border: "1px solid #e1e3e5",
        borderRadius: "8px",
        overflow: "hidden",
        fontSize: "13px",
      }}
    >
      <div
        style={{
          background: "#f6f6f7",
          padding: "12px 16px",
          borderBottom: "1px solid #e1e3e5",
          fontWeight: 600,
          fontSize: "14px",
        }}
      >
        {name || "Size Chart Preview"}
      </div>
      <div style={{ overflowX: "auto" }}>
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            fontSize: "13px",
          }}
        >
          <thead>
            <tr>
              {data.headers.map((h, i) => (
                <th
                  key={i}
                  style={{
                    background: "#f6f6f7",
                    padding: "8px 12px",
                    textAlign: "left",
                    fontWeight: 600,
                    borderBottom: "2px solid #e1e3e5",
                    borderRight: i < data.headers.length - 1 ? "1px solid #e1e3e5" : "none",
                    whiteSpace: "nowrap",
                  }}
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {data.rows.map((row, ri) => (
              <tr
                key={ri}
                style={{ background: ri % 2 === 0 ? "#fff" : "#fafbfb" }}
              >
                {data.headers.map((h, hi) => (
                  <td
                    key={hi}
                    style={{
                      padding: "8px 12px",
                      borderBottom: "1px solid #e1e3e5",
                      borderRight:
                        hi < data.headers.length - 1 ? "1px solid #e1e3e5" : "none",
                      color: row[h] ? "#202223" : "#8c9196",
                    }}
                  >
                    {row[h] || "—"}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div
        style={{
          padding: "8px 16px",
          background: "#f6f6f7",
          borderTop: "1px solid #e1e3e5",
          fontSize: "12px",
          color: "#6d7175",
        }}
      >
        Units: {data.units.default} · {data.rows.length} sizes
      </div>
    </div>
  );
}

