// Main Component
// ---------------------------------------------------------------------------

type LoaderData = Awaited<ReturnType<typeof loader>>;

export default function SizeChartEditor() {
  const loaderData = useLoaderData<typeof loader>() as LoaderData;
  const { chart, assignments: initialAssignments, isNew } = loaderData;

  const saveFetcher = useFetcher<typeof action>();
  const statusFetcher = useFetcher<typeof action>();
  const assignmentFetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [name, setName] = useState(chart?.name ?? "Untitled Size Chart");
  const [category, setCategory] = useState(chart?.category ?? "general");
  const [status, setStatus] = useState(chart?.status ?? "draft");
  const [chartData, setChartData] = useState<ChartData>(
    chart ? parseChartData(chart.data) : makeDefaultData()
  );
  const [assignments, setAssignments] = useState<Assignment[]>(initialAssignments);
  const [newAssignmentType, setNewAssignmentType] = useState("product");
  const [newAssignmentValue, setNewAssignmentValue] = useState("");

  const isSaving = saveFetcher.state !== "idle";
  const isTogglingStatus = statusFetcher.state !== "idle";

  // Check for ?saved=1 on mount (after redirect from new chart creation)
  useEffect(() => {
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      if (url.searchParams.get("saved") === "1") {
        shopify.toast.show("Chart created successfully");
        url.searchParams.delete("saved");
        window.history.replaceState({}, "", url.toString());
      }
    }
  }, [shopify]);

  // Save feedback
  useEffect(() => {
    if (!saveFetcher.data) return;
    const data = saveFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Saved");
    } else if ("error" in data) {
      shopify.toast.show(data.error, { isError: true });
    }
  }, [saveFetcher.data, shopify]);

  // Status toggle feedback
  useEffect(() => {
    if (!statusFetcher.data) return;
    const data = statusFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Status updated");
      if ("newStatus" in data && typeof data.newStatus === "string") {
        setStatus(data.newStatus);
      }
    } else if ("error" in data) {
      shopify.toast.show(data.error, { isError: true });
    }
  }, [statusFetcher.data, shopify]);

  // Assignment feedback
  useEffect(() => {
    if (!assignmentFetcher.data) return;
    const data = assignmentFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Done");
      setNewAssignmentValue("");
    } else if ("error" in data) {
      shopify.toast.show(data.error, { isError: true });
    }
  }, [assignmentFetcher.data, shopify]);

  const handleSave = () => {
    const formData = new FormData();
    formData.set("intent", "save");
    formData.set("name", name);
    formData.set("category", category);
    formData.set("status", status);
    formData.set("data", JSON.stringify(chartData));
    saveFetcher.submit(formData, { method: "post" });
  };

  const handleToggleStatus = () => {
    const formData = new FormData();
    formData.set("intent", "toggle-status");
    statusFetcher.submit(formData, { method: "post" });
  };

  const handleAddAssignment = () => {
    if (!newAssignmentValue.trim() && newAssignmentType !== "all") return;
    const formData = new FormData();
    formData.set("intent", "add-assignment");
    formData.set("assignmentType", newAssignmentType);
    formData.set(
      "assignmentValue",
      newAssignmentType === "all" ? "*" : newAssignmentValue.trim()
    );
    assignmentFetcher.submit(formData, { method: "post" });
    setAssignments((prev) => [
      ...prev,
      {
        id: `temp-${Date.now()}`,
        assignmentType: newAssignmentType,
        assignmentValue: newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
      },
    ]);
  };

  const handleRemoveAssignment = (assignmentId: string) => {
    const formData = new FormData();
    formData.set("intent", "remove-assignment");
    formData.set("assignmentId", assignmentId);
    assignmentFetcher.submit(formData, { method: "post" });
    setAssignments((prev) => prev.filter((a) => a.id !== assignmentId));
  };

  const assignmentTypeLabel = (type: string) =>
    ASSIGNMENT_TYPES.find((t) => t.value === type)?.label ?? type;

  return (
    <s-page
      heading={isNew ? "New Size Chart" : name}
      back-action-url="/app/size-charts"
    >
      <s-button
        slot="primary-action"
        variant="primary"
        onClick={handleSave}
        loading={isSaving}
        disabled={isSaving}
      >
        Save
      </s-button>

      <s-button
        slot="secondary-action"
        onClick={handleToggleStatus}
        loading={isTogglingStatus}
        disabled={isNew || isTogglingStatus}
      >
        {status === "active" ? "Unpublish" : "Publish"}
      </s-button>

      {/* Chart Details */}
      <s-section heading="Chart Details">
        <s-stack direction="block" gap="base">
          <s-stack direction="block" gap="small-100">
            <s-text>Name</s-text>
            <input
              value={name}
              onChange={(e) => setName((e.target as HTMLInputElement).value)}
              placeholder="e.g. Women's Tops Size Chart"
              style={{
                width: "100%",
                border: "1px solid #8c9196",
                borderRadius: "6px",
                padding: "8px 12px",
                fontSize: "14px",
                color: "#202223",
                background: "#fff",
                boxSizing: "border-box",
                outline: "none",
              }}
              onFocus={(e) => {
                (e.target as HTMLInputElement).style.borderColor = "#2c6ecb";
                (e.target as HTMLInputElement).style.boxShadow =
                  "0 0 0 3px rgba(44,110,203,0.15)";
              }}
              onBlur={(e) => {
                (e.target as HTMLInputElement).style.borderColor = "#8c9196";
                (e.target as HTMLInputElement).style.boxShadow = "none";
              }}
            />
          </s-stack>

          <s-stack direction="inline" gap="base">
            <s-stack direction="block" gap="small-100" style={{ flex: 1 }}>
              <s-text>Category</s-text>
              <select
                value={category}
                onChange={(e) => setCategory((e.target as HTMLSelectElement).value)}
                style={{
                  width: "100%",
                  border: "1px solid #8c9196",
                  borderRadius: "6px",
                  padding: "8px 12px",
                  fontSize: "14px",
                  color: "#202223",
                  background: "#fff",
                  boxSizing: "border-box",
                  cursor: "pointer",
                }}
              >
                {CATEGORIES.map((c) => (
                  <option key={c.value} value={c.value}>
                    {c.label}
                  </option>
                ))}
              </select>
            </s-stack>

            <s-stack direction="block" gap="small-100">
              <s-text>Status</s-text>
              <div style={{ paddingTop: "8px" }}>
                {status === "active" ? (
                  <s-badge tone="success">Published</s-badge>
                ) : (
                  <s-badge>Draft</s-badge>
                )}
              </div>
            </s-stack>
          </s-stack>
        </s-stack>
      </s-section>

      {/* Table Editor */}
      <s-section heading="Size Table">
        <s-paragraph>
          Click any cell to edit. Use the + buttons to add rows or columns. Column
          names are editable — click the header text to rename.
        </s-paragraph>
        <div style={{ marginTop: "16px" }}>
          <TableEditor data={chartData} onChange={setChartData} />
        </div>
      </s-section>

      {/* Product Assignments */}
      <s-section heading="Product Assignments">
        <s-paragraph>
          Assign this chart to products, collections, or tags. The widget will
          automatically display this chart on matching product pages.
        </s-paragraph>

        {assignments.length > 0 && (
          <div style={{ marginTop: "16px", marginBottom: "16px" }}>
            <s-stack direction="block" gap="small-200">
              {assignments.map((assignment) => (
                <s-box
                  key={assignment.id}
                  padding="base"
                  borderWidth="base"
                  borderRadius="base"
                >
                  <s-stack direction="inline" gap="base">
                    <s-stack direction="block" gap="small-100" style={{ flex: 1 }}>
                      <s-badge tone="info">
                        {assignmentTypeLabel(assignment.assignmentType)}
                      </s-badge>
                      <s-text>
                        {assignment.assignmentValue === "*"
                          ? "All products"
                          : assignment.assignmentValue}
                      </s-text>
                    </s-stack>
                    <button
                      type="button"
                      onClick={() => handleRemoveAssignment(assignment.id)}
                      style={{
                        background: "none",
                        border: "none",
                        cursor: "pointer",
                        color: "#d82c0d",
                        fontSize: "13px",
                        fontWeight: 500,
                        padding: "4px 8px",
                      }}
                    >
                      Remove
                    </button>
                  </s-stack>
                </s-box>
              ))}
            </s-stack>
          </div>
        )}

        {assignments.length === 0 && (
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text tone="neutral">
              No assignments yet. Add an assignment below to display this chart on product pages.
            </s-text>
          </s-box>
        )}

        {!isNew && (
          <div style={{ marginTop: "16px" }}>
            <s-stack direction="block" gap="small-200">
              <s-text>Add Assignment</s-text>
              <s-stack direction="inline" gap="small-200">
                <select
                  value={newAssignmentType}
                  onChange={(e) =>
                    setNewAssignmentType((e.target as HTMLSelectElement).value)
                  }
                  style={{
                    border: "1px solid #8c9196",
                    borderRadius: "6px",
                    padding: "8px 10px",
                    fontSize: "14px",
                    background: "#fff",
                    cursor: "pointer",
                  }}
                >
                  {ASSIGNMENT_TYPES.map((t) => (
                    <option key={t.value} value={t.value}>
                      {t.label}
                    </option>
                  ))}
                </select>

                {newAssignmentType !== "all" && (
                  <input
                    value={newAssignmentValue}
                    onChange={(e) =>
                      setNewAssignmentValue((e.target as HTMLInputElement).value)
                    }
                    placeholder={
                      newAssignmentType === "tag"
                        ? "e.g. summer-sale"
                        : newAssignmentType === "product_type"
                        ? "e.g. T-Shirts"
                        : "e.g. gid://shopify/Product/123"
                    }
                    style={{
                      flex: 1,
                      border: "1px solid #8c9196",
                      borderRadius: "6px",
                      padding: "8px 12px",
                      fontSize: "14px",
                      background: "#fff",
                    }}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") {
                        e.preventDefault();
                        handleAddAssignment();
                      }
                    }}
                  />
                )}

                <s-button
                  variant="primary"
                  onClick={handleAddAssignment}
                  loading={assignmentFetcher.state !== "idle"}
                >
                  Add
                </s-button>
              </s-stack>
              <s-text tone="neutral">
                Save the chart first, then add assignments.
              </s-text>
            </s-stack>
          </div>
        )}

        {isNew && (
          <s-banner tone="info">
            <s-paragraph>Save the chart first to add product assignments.</s-paragraph>
          </s-banner>
        )}
      </s-section>

      {/* Sidebar — Live Preview */}
      <s-section slot="aside" heading="Preview">
        <ChartPreview data={chartData} name={name} />
      </s-section>

      {/* Sidebar — Chart Info */}
      {!isNew && chart && (
        <s-section slot="aside" heading="Chart Info">
          <s-stack direction="block" gap="small-200">
            <s-stack direction="block" gap="small-100">
              <s-text tone="neutral">Created</s-text>
              <s-text>{formatDate(chart.createdAt)}</s-text>
            </s-stack>
            <s-stack direction="block" gap="small-100">
              <s-text tone="neutral">Last updated</s-text>
              <s-text>{formatDate(chart.updatedAt)}</s-text>
            </s-stack>
            <s-stack direction="block" gap="small-100">
              <s-text tone="neutral">Assignments</s-text>
              <s-text>{assignments.length}</s-text>
            </s-stack>
            <s-stack direction="block" gap="small-100">
              <s-text tone="neutral">Rows</s-text>
              <s-text>{chartData.rows.length}</s-text>
            </s-stack>
          </s-stack>
        </s-section>
      )}

      {/* Sidebar — Danger Zone */}
      {!isNew && (
        <s-section slot="aside" heading="Danger Zone">
          <assignmentFetcher.Form method="post">
            <input type="hidden" name="intent" value="delete" />
            <s-button
              type="submit"
              tone="critical"
              variant="tertiary"
            >
              Delete Chart
            </s-button>
          </assignmentFetcher.Form>
          <s-text tone="neutral">
            Permanently deletes the chart and all assignments. This cannot be undone.
          </s-text>
        </s-section>
      )}
    </s-page>
  );
}

