267→          </s-paragraph>
268→
269→          <div
270→            style={{
271→              display: "grid",
272→              gridTemplateColumns: "repeat(auto-fill, minmax(200px, 1fr))",
273→              gap: "12px",
274→              marginTop: "16px",
275→            }}
276→          >
277→            {templates.map((template) => (
278→              <div
279→                key={template.name}
280→                style={{
281→                  border: "1px solid #e1e3e5",
282→                  borderRadius: "8px",
283→                  padding: "16px",
284→                  background: "#fff",
285→                }}
286→              >
287→                <s-stack direction="block" gap="small-200">
288→                  <s-text>{template.name}</s-text>
289→                  <s-text tone="neutral">
290→                    {CATEGORY_LABELS[template.category] ?? template.category} ·{" "}
291→                    {template.gender} · {template.rowCount} sizes
292→                  </s-text>
293→                  <fetcher.Form method="post">
294→                    <input type="hidden" name="intent" value="create-from-template" />
295→                    <input type="hidden" name="templateName" value={template.name} />
296→                    <s-button variant="primary" type="submit" loading={isLoading}>
297→                      Use Template
298→                    </s-button>
299→                  </fetcher.Form>
300→                </s-stack>
301→              </div>
302→            ))}
303→
304→            <div
305→              style={{
306→                border: "2px dashed #b5b9bc",
307→                borderRadius: "8px",
308→                padding: "16px",
309→                background: "#f6f6f7",
310→              }}
311→            >
312→              <s-stack direction="block" gap="small-200">
313→                <s-text>Blank Chart</s-text>
314→                <s-text tone="neutral">Start from scratch with your own columns</s-text>
315→                <fetcher.Form method="post">
316→                  <input type="hidden" name="intent" value="create-blank" />
317→                  <input type="hidden" name="name" value="Untitled Size Chart" />
318→                  <input type="hidden" name="category" value="general" />
319→                  <s-button type="submit" loading={isLoading}>
320→                    Create Blank
321→                  </s-button>
322→                </fetcher.Form>
323→              </s-stack>
324→            </div>
325→          </div>
326→        </s-section>
327→      )}
328→
329→      <s-section>
330→        <s-stack direction="inline" gap="base">
331→          <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
332→            <s-text tone="neutral">Category:</s-text>
333→            <select
334→              value={categoryFilter}
335→              onChange={(e) => setCategoryFilter((e.target as HTMLSelectElement).value)}
336→              style={{
337→                border: "1px solid #8c9196",
338→                borderRadius: "6px",
339→                padding: "6px 10px",
340→                fontSize: "14px",
341→                background: "#fff",
342→                cursor: "pointer",
343→              }}
344→            >
