346→              {categories.map((cat) => (
347→                <option key={cat} value={cat}>
348→                  {CATEGORY_LABELS[cat] ?? cat}
349→                </option>
350→              ))}
351→            </select>
352→          </div>
353→
354→          <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
355→            <s-text tone="neutral">Status:</s-text>
356→            <select
357→              value={statusFilter}
358→              onChange={(e) => setStatusFilter((e.target as HTMLSelectElement).value)}
359→              style={{
360→                border: "1px solid #8c9196",
361→                borderRadius: "6px",
362→                padding: "6px 10px",
363→                fontSize: "14px",
